echarts.保值率曲线模板:
var valueCurveSeries = curves.map(function(c, i) {
  return { name: c.name, type: 'line', smooth: true, symbol: 'circle', symbolSize: 6, data: c.data,
    lineStyle: { color: PALETTE[i % PALETTE.length], width: 2.5 }, itemStyle: { color: PALETTE[i % PALETTE.length] } };
});
valueCurveSeries.push({
  type: 'line', data: [], symbol: 'none',
  markLine: { symbol: 'none', silent: true, lineStyle: { color: C_WARNING, type: 'dashed' },
    data: [{ xAxis: 60, label: { formatter: 'macOS支持期~72月', color: C_WARNING } }] }
});
var valueCurveOption = Object.assign({}, baseOption, {
  xAxis: { name: '机龄(发布后月数)', min: 0, max: 60 },
  yAxis: { name: '保值率%', min: 0, max: 100 },
  tooltip: { trigger: 'axis' },
  series: valueCurveSeries
});

